import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.uTHcANy5.js";const m=JSON.parse('{"title":"The standard and its implementations","description":"","frontmatter":{},"headers":[],"relativePath":"standard/index.md","filePath":"standard/index.md"}'),i={name:"standard/index.md"};function o(d,e,r,h,c,l){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-standard-and-its-implementations" tabindex="-1">The standard and its implementations <a class="header-anchor" href="#the-standard-and-its-implementations" aria-label="Permalink to &quot;The standard and its implementations&quot;">​</a></h1><p>Mosaic is three different things kept in one repository. They change at different speeds and promise different things:</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it is</th><th>Where it lives</th><th>What it promises</th></tr></thead><tbody><tr><td><strong>The standard</strong></td><td>The shape of a Mosaic file and of the HTTP API, as JSON Schema and OpenAPI</td><td><a href="https://github.com/tomvandig/mosaic/tree/main/standard/" target="_blank" rel="noreferrer"><code>standard/</code></a>, generated from <a href="https://github.com/tomvandig/mosaic/tree/main/src/" target="_blank" rel="noreferrer"><code>src/</code></a></td><td>What any reader or writer, in any language, can rely on</td></tr><tr><td><strong>The reference implementation</strong></td><td>The TypeScript SDK, the IFC converter and the viewer</td><td><a href="https://github.com/tomvandig/mosaic/tree/main/sdk/ts/" target="_blank" rel="noreferrer"><code>sdk/ts</code></a>, <a href="https://github.com/tomvandig/mosaic/tree/main/sdk/ifc4/" target="_blank" rel="noreferrer"><code>sdk/ifc4</code></a></td><td>One working reading of the standard, plus conventions built on top of it</td></tr><tr><td><strong>The CLI</strong></td><td>The <code>mosaic</code> command</td><td><a href="https://github.com/tomvandig/mosaic/tree/main/sdk/cli/" target="_blank" rel="noreferrer"><code>sdk/cli</code></a></td><td>A thin wrapper exposing the reference implementation as commands</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/*.tsp ──tsp compile──▶ standard/*.json ──quicktype──▶ sdk/ts (types)</span></span>
<span class="line"><span>                                                          │</span></span>
<span class="line"><span>                                       sdk/ts + sdk/ifc4 ─┴─▶ sdk/cli  (mosaic …)</span></span>
<span class="line"><span>                                                          └─▶ viewer</span></span></code></pre></div><p>The arrows only go one way. The standard does not know the SDK exists. The SDK&#39;s types are <em>generated</em> from the standard, and the CLI adds no behaviour of its own: every command calls a function in the SDK that you can also call from your own code.</p><div class="warning custom-block"><p class="custom-block-title">Pre-1.0</p><p>All three layers are still moving, the standard included. Its version string (<code>MosaicVersion</code>) is currently <code>&quot;post-alpha&quot;</code>.</p></div><h2 id="why-the-split-matters" tabindex="-1">Why the split matters <a class="header-anchor" href="#why-the-split-matters" aria-label="Permalink to &quot;Why the split matters&quot;">​</a></h2><p><strong>If you are writing another implementation</strong>, in C#, Python or Rust, the standard is the contract. Validate against <a href="/mosaic/dist/docs/standard/file/#the-index-file"><code>mosaic-index-file.schema.json</code></a> and you can read and write Mosaic without any of the TypeScript code.</p><p><strong>If you are using Mosaic from TypeScript</strong>, the SDK gives you a lot more than the standard does: packing, federating, selecting, composing to glTF, converters and a database. Most of that is <a href="/mosaic/dist/docs/sdk/#what-the-implementation-adds">behaviour the schemas do not define</a>, so another implementation may not do it, or may do it differently.</p><p><strong>If you only want the tools</strong>, the CLI is all you need. It ships as a single executable, and everything it does is described in <a href="/mosaic/dist/docs/tools/">The CLI</a> section of these docs.</p><h2 id="generating-the-standard" tabindex="-1">Generating the standard <a class="header-anchor" href="#generating-the-standard" aria-label="Permalink to &quot;Generating the standard&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile-json-spec</span></span></code></pre></div><p>The TypeSpec compiler reads <a href="https://github.com/tomvandig/mosaic/blob/main/src/mosaic-json-file.tsp" target="_blank" rel="noreferrer"><code>mosaic-json-file.tsp</code></a> and writes <a href="https://github.com/tomvandig/mosaic/blob/main/standard/mosaic-index-file.schema.json" target="_blank" rel="noreferrer"><code>standard/mosaic-index-file.schema.json</code></a>, as configured in <a href="https://github.com/tomvandig/mosaic/blob/main/src/tspconfig.yaml" target="_blank" rel="noreferrer"><code>tspconfig.yaml</code></a>. Commit the regenerated output alongside the spec change. The <a href="/mosaic/dist/docs/standard/api">API standard</a> is generated the same way, with <code>npm run compile-api-spec</code>.</p><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="/mosaic/dist/docs/standard/file/">File standard</a>: the index file schema, field by field, and how it is generated. <a href="/mosaic/dist/docs/standard/file/format">The format, by example</a> opens up a real archive.</li><li><a href="/mosaic/dist/docs/standard/api">API standard</a>: the OpenAPI description of the HTTP API.</li></ul><p>The reference implementation is described in <a href="/mosaic/dist/docs/sdk/">The SDK</a> and <a href="/mosaic/dist/docs/tools/">The CLI</a>: what they build on top of the standard, and where they currently fall short of it.</p>`,16)])])}const g=a(i,[["render",o]]);export{m as __pageData,g as default};
